119	// WatchEvictionEventsWithRetries watches new Events with reason=Evicted and passes them to the observer.
120	func WatchEvictionEventsWithRetries(ctx context.Context, kubeClient kube_client.Interface, observer oom.Observer, namespace string) {
121		go func() {
122			options := metav1.ListOptions{
123				FieldSelector: "reason=Evicted",
124			}
125	
126			watchEvictionEventsOnce := func() {
127				watchInterface, err := kubeClient.CoreV1().Events(namespace).Watch(ctx, options)
128				if err != nil {
129					klog.ErrorS(err, "Cannot initialize watching events")
130					return
131				}
132				defer watchInterface.Stop()
133				watchEvictionEvents(watchInterface.ResultChan(), observer)
134			}
135			for {
136				select {
137				case <-ctx.Done():
138					return
139				default:
140					watchEvictionEventsOnce()
141					// Wait between attempts, retrying too often breaks API server.
142					waitTime := wait.Jitter(evictionWatchRetryWait, evictionWatchJitterFactor)
143					klog.V(1).InfoS("An attempt to watch eviction events finished", "waitTime", waitTime)
144					select {
145					case <-ctx.Done():
146						return
147					case <-time.After(waitTime):
148					}
149				}
150			}
151		}()
152	}
153	
154	func watchEvictionEvents(evictedEventChan <-chan watch.Event, observer oom.Observer) {
155		for {
156			evictedEvent, ok := <-evictedEventChan
157			if !ok {
158				klog.V(3).InfoS("Eviction event chan closed")
159				return
160			}
161			if evictedEvent.Type == watch.Added {
162				evictedEvent, ok := evictedEvent.Object.(*corev1.Event)
163				if !ok {
164					continue
165				}
166				observer.OnEvent(evictedEvent)
167			}
168		}
169	}
