171	// Creates clients watching pods: PodLister (listing only not terminated pods).
172	func newPodClients(kubeClient kube_client.Interface, resourceEventHandler cache.ResourceEventHandler, namespace string, stopCh <-chan struct{}) listersv1.PodLister {
173		// We are interested in pods which are Running or Unknown (in case the pod is
174		// running but there are some transient errors we don't want to delete it from
175		// our model).
176		// We don't want to watch Pending pods because they didn't generate any usage
177		// yet.
178		// Succeeded and Failed failed pods don't generate any usage anymore but we
179		// don't necessarily want to immediately delete them.
180		selector := fields.ParseSelectorOrDie("status.phase!=" + string(corev1.PodPending))
181		podListWatch := cache.NewListWatchFromClient(kubeClient.CoreV1().RESTClient(), "pods", namespace, selector)
182		informerOptions := cache.InformerOptions{
183			ObjectType:    &corev1.Pod{},
184			ListerWatcher: podListWatch,
185			Handler:       resourceEventHandler,
186			ResyncPeriod:  time.Hour,
187			Indexers:      cache.Indexers{cache.NamespaceIndex: cache.MetaNamespaceIndexFunc},
188			Transform:     client.StripManagedFields,
189		}
190	
191		store, controller := cache.NewInformerWithOptions(informerOptions)
192		indexer, ok := store.(cache.Indexer)
193		if !ok {
194			klog.ErrorS(nil, "Expected Indexer, but got a Store that does not implement Indexer")
195			klog.FlushAndExit(klog.ExitFlushTimeout, 1)
196		}
197		podLister := listersv1.NewPodLister(indexer)
198		go controller.Run(stopCh)
199		if !cache.WaitForCacheSync(stopCh, controller.HasSynced) {
200			klog.ErrorS(nil, "Failed to sync Pod cache during initialization")
201		}
202		return podLister
203	}
