205	// NewPodListerAndOOMObserver creates pair of pod lister and OOM observer.
206	func NewPodListerAndOOMObserver(ctx context.Context, kubeClient kube_client.Interface, namespace string, stopCh <-chan struct{}) (listersv1.PodLister, oom.Observer) {
207		oomObserver := oom.NewObserver()
208		podLister := newPodClients(kubeClient, oomObserver, namespace, stopCh)
209		WatchEvictionEventsWithRetries(ctx, kubeClient, oomObserver, namespace)
210		return podLister, oomObserver
211	}
