230	func (feeder *clusterStateFeeder) InitFromHistoryProvider(historyProvider history.HistoryProvider) {
231		klog.V(3).InfoS("Initializing VPA from history provider")
232		clusterHistory, err := historyProvider.GetClusterHistory()
233		if err != nil {
234			klog.ErrorS(err, "Cannot get cluster history")
235		}
236		for podID, podHistory := range clusterHistory {
237			klog.V(4).InfoS("Adding pod with labels", "pod", podID, "labels", podHistory.LastLabels)
238			feeder.clusterState.AddOrUpdatePod(podID, podHistory.LastLabels, corev1.PodUnknown)
239			for containerName, sampleList := range podHistory.Samples {
240				containerID := model.ContainerID{
241					PodID:         podID,
242					ContainerName: containerName,
243				}
244				if err = feeder.clusterState.AddOrUpdateContainer(containerID, nil); err != nil {
245					klog.V(0).InfoS("Failed to add container", "container", containerID, "error", err)
246				}
247				klog.V(4).InfoS("Adding samples for container", "sampleCount", len(sampleList), "container", containerID)
248				for _, sample := range sampleList {
249					if err := feeder.clusterState.AddSample(
250						&model.ContainerUsageSampleWithKey{
251							ContainerUsageSample: sample,
252							Container:            containerID,
253						}); err != nil {
254						klog.V(0).InfoS("Failed to add sample", "sample", sample, "error", err)
255					}
256				}
257			}
258		}
259	}
