261	func (feeder *clusterStateFeeder) InitFromCheckpoints(ctx context.Context) {
262		klog.V(3).InfoS("Initializing VPA from checkpoints")
263		feeder.LoadVPAs(ctx)
264	
265		checkpointList, err := feeder.vpaCheckpointLister.List(labels.Everything())
266		if err != nil {
267			klog.ErrorS(err, "Cannot list VPA checkpoints")
268		}
269		klog.V(3).InfoS("Fetching VPA checkpoints", "count", len(checkpointList))
270	
271		vpas := feeder.clusterState.VPAs()
272		for _, checkpoint := range checkpointList {
273			vpaID := model.VpaID{Namespace: checkpoint.Namespace, VpaName: checkpoint.Spec.VPAObjectName}
274			vpa, found := vpas[vpaID]
275			if !found {
276				klog.V(4).InfoS("Skipping loading checkpoint: VPA not tracked by this recommender", "checkpoint", klog.KObj(checkpoint), "vpa", klog.KRef(vpaID.Namespace, vpaID.VpaName), "recommenderName", feeder.recommenderName)
277				continue
278			}
279			klog.V(3).InfoS("Loading checkpoint for VPA", "checkpoint", klog.KObj(checkpoint), "vpa", klog.KRef(vpaID.Namespace, vpaID.VpaName), "container", checkpoint.Spec.ContainerName)
280			cs := model.NewAggregateContainerState()
281			if err := cs.LoadFromCheckpoint(&checkpoint.Status); err != nil {
282				klog.ErrorS(err, "Failed loading checkpoint", "checkpoint", klog.KObj(checkpoint), "vpa", klog.KRef(vpaID.Namespace, vpaID.VpaName))
283				continue
284			}
285			vpa.ContainersInitialAggregateState[checkpoint.Spec.ContainerName] = cs
286		}
287	}
