357	// Filter VPA objects whose specified recommender names are not default
358	func filterVPAs(feeder *clusterStateFeeder, allVpaCRDs []*vpa_types.VerticalPodAutoscaler) []*vpa_types.VerticalPodAutoscaler {
359		klog.V(3).InfoS("Start selecting the vpaCRDs.")
360		var vpaCRDs []*vpa_types.VerticalPodAutoscaler
361		for _, vpaCRD := range allVpaCRDs {
362			if feeder.recommenderName == DefaultRecommenderName {
363				if !implicitDefaultRecommender(vpaCRD.Spec.Recommenders) && !selectsRecommender(vpaCRD.Spec.Recommenders, &feeder.recommenderName) {
364					klog.V(6).InfoS("Ignoring vpaCRD as current recommender's name doesn't appear among its recommenders", "vpaCRD", klog.KObj(vpaCRD), "recommenderName", feeder.recommenderName)
365					continue
366				}
367			} else {
368				if implicitDefaultRecommender(vpaCRD.Spec.Recommenders) {
369					klog.V(6).InfoS("Ignoring vpaCRD as recommender doesn't process CRDs implicitly destined to default recommender", "vpaCRD", klog.KObj(vpaCRD), "recommenderName", feeder.recommenderName, "defaultRecommenderName", DefaultRecommenderName)
370					continue
371				}
372				if !selectsRecommender(vpaCRD.Spec.Recommenders, &feeder.recommenderName) {
373					klog.V(6).InfoS("Ignoring vpaCRD as current recommender's name doesn't appear among its recommenders", "vpaCRD", klog.KObj(vpaCRD), "recommenderName", feeder.recommenderName)
374					continue
375				}
376			}
377	
378			if feeder.shouldIgnoreNamespace(vpaCRD.Namespace) {
379				klog.V(6).InfoS("Ignoring vpaCRD as this namespace is ignored", "vpaCRD", klog.KObj(vpaCRD))
380				continue
381			}
382	
383			vpaCRDs = append(vpaCRDs, vpaCRD)
384		}
385		return vpaCRDs
386	}
