388	// LoadVPAs fetches VPA objects and loads them into the cluster state.
389	func (feeder *clusterStateFeeder) LoadVPAs(ctx context.Context) {
390		// List VPA API objects.
391		allVpaCRDs, err := feeder.vpaLister.List(labels.Everything())
392		if err != nil {
393			klog.ErrorS(err, "Cannot list VPAs")
394			return
395		}
396	
397		// Filter out VPAs that specified recommenders with names not equal to "default"
398		vpaCRDs := filterVPAs(feeder, allVpaCRDs)
399	
400		klog.V(3).InfoS("Fetching VPAs", "count", len(vpaCRDs))
401		// Add or update existing VPAs in the model.
402		vpaKeys := make(map[model.VpaID]bool)
403		for _, vpaCRD := range vpaCRDs {
404			vpaID := model.VpaID{
405				Namespace: vpaCRD.Namespace,
406				VpaName:   vpaCRD.Name,
407			}
408	
409			selector, conditions := feeder.getSelector(ctx, vpaCRD)
410			klog.V(4).InfoS("Using selector", "selector", selector.String(), "vpa", klog.KObj(vpaCRD))
411	
412			if feeder.clusterState.AddOrUpdateVpa(vpaCRD, selector) == nil {
413				// Successfully added VPA to the model.
414				vpaKeys[vpaID] = true
415	
416				for _, condition := range conditions {
417					if condition.delete {
418						feeder.clusterState.VPAs()[vpaID].DeleteCondition(condition.conditionType)
419					} else {
420						feeder.clusterState.VPAs()[vpaID].SetCondition(condition.conditionType, true, "", condition.message)
421					}
422				}
423			}
424		}
425		// Delete non-existent VPAs from the model.
426		for vpaID := range feeder.clusterState.VPAs() {
427			if _, exists := vpaKeys[vpaID]; !exists {
428				klog.V(3).InfoS("Deleting VPA", "vpa", klog.KRef(vpaID.Namespace, vpaID.VpaName))
429				if err := feeder.clusterState.DeleteVpa(vpaID); err != nil {
430					klog.ErrorS(err, "Deleting VPA failed", "vpa", klog.KRef(vpaID.Namespace, vpaID.VpaName))
431				}
432			}
433		}
434		feeder.clusterState.SetObservedVPAs(vpaCRDs)
435	}
