437	// LoadPods loads pod into the cluster state.
438	func (feeder *clusterStateFeeder) LoadPods() {
439		podSpecs, err := feeder.specClient.GetPodSpecs()
440		if err != nil {
441			klog.ErrorS(err, "Cannot get SimplePodSpecs, skipping LoadPods cycle")
442			return
443		}
444		pods := make(map[model.PodID]*spec.BasicPodSpec)
445		for _, spec := range podSpecs {
446			pods[spec.ID] = spec
447		}
448		feeder.podsToDelete = nil
449		for key := range feeder.clusterState.Pods() {
450			// The pods aren't deleted from the clusterState while loading pods since OomInfo from these removed containers
451			// may still need to be processed. We delete these pods after the OomInfo is processed.
452			if _, exists := pods[key]; !exists {
453				feeder.podsToDelete = append(feeder.podsToDelete, key)
454			}
455		}
456		for _, pod := range pods {
457			if feeder.memorySaveMode && !feeder.matchesVPA(pod) {
458				continue
459			}
460			feeder.clusterState.AddOrUpdatePod(pod.ID, pod.PodLabels, pod.Phase)
461			for _, container := range pod.Containers {
462				if err = feeder.clusterState.AddOrUpdateContainer(container.ID, container.Request); err != nil {
463					klog.V(0).InfoS("Failed to add container", "container", container.ID, "error", err)
464				}
465			}
466			initContainerNames := make([]string, 0, len(pod.InitContainers))
467			for _, initContainer := range pod.InitContainers {
468				initContainerNames = append(initContainerNames, initContainer.ID.ContainerName)
469			}
470			if err = feeder.clusterState.SetInitContainers(pod.ID, initContainerNames); err != nil {
471				klog.V(0).InfoS("Failed to set init containers", "pod", klog.KRef(pod.ID.Namespace, pod.ID.PodName), "error", err)
472			}
473		}
474	}
475	
476	// DeleteRemovedPods deletes pods that were identified as removed in the last LoadPods call.
477	func (feeder *clusterStateFeeder) DeleteRemovedPods() {
478		for _, key := range feeder.podsToDelete {
479			klog.V(3).InfoS("Deleting Pod", "pod", klog.KRef(key.Namespace, key.PodName))
480			feeder.clusterState.DeletePod(key)
481		}
482		feeder.podsToDelete = nil
483	}
