485	func (feeder *clusterStateFeeder) LoadRealTimeMetrics(ctx context.Context) {
486		containersMetrics, err := feeder.metricsClient.GetContainersMetrics(ctx)
487		if err != nil {
488			klog.ErrorS(err, "Cannot get ContainerMetricsSnapshot from MetricsClient")
489		}
490	
491		sampleCount := 0
492		droppedSampleCount := 0
493		for _, containerMetrics := range containersMetrics {
494			// Container metrics are fetched for all pods, however, not all pod states are tracked in memory saver mode.
495			if pod, exists := feeder.clusterState.Pods()[containerMetrics.ID.PodID]; exists && pod != nil {
496				if slices.Contains(pod.InitContainers, containerMetrics.ID.ContainerName) {
497					klog.V(3).InfoS("Skipping metric samples for init container", "pod", klog.KRef(containerMetrics.ID.Namespace, containerMetrics.ID.PodName), "container", containerMetrics.ID.ContainerName)
498					droppedSampleCount += len(containerMetrics.Usage)
499					continue
500				}
501			}
502			for _, sample := range newContainerUsageSamplesWithKey(containerMetrics) {
503				if err := feeder.clusterState.AddSample(sample); err != nil {
504					// Not all pod states are tracked in memory saver mode.
505					if _, isKeyError := err.(model.KeyError); isKeyError && feeder.memorySaveMode {
506						continue
507					}
508					klog.V(0).InfoS("Error adding metric sample", "sample", sample, "error", err)
509					droppedSampleCount++
510				} else {
511					sampleCount++
512				}
513			}
514		}
515		klog.V(3).InfoS("ClusterSpec fed with ContainerUsageSamples", "sampleCount", sampleCount, "containerCount", len(containersMetrics), "droppedSampleCount", droppedSampleCount)
516	Loop:
517		for {
518			select {
519			case oomInfo := <-feeder.oomChan:
520				klog.V(3).InfoS("OOM detected", "oomInfo", oomInfo)
521				if err = feeder.clusterState.RecordOOM(oomInfo.ContainerID, oomInfo.Timestamp, oomInfo.Memory); err != nil {
522					klog.V(0).InfoS("Failed to record OOM", "oomInfo", oomInfo, "error", err)
523				}
524			default:
525				break Loop
526			}
527		}
528		metrics_recommender.RecordAggregateContainerStatesCount(feeder.clusterState.StateMapSize())
529	}
