531	func (feeder *clusterStateFeeder) matchesVPA(pod *spec.BasicPodSpec) bool {
532		for vpaKey, vpa := range feeder.clusterState.VPAs() {
533			podLabels := labels.Set(pod.PodLabels)
534			if vpaKey.Namespace == pod.ID.Namespace && vpa.PodSelector.Matches(podLabels) {
535				return true
536			}
537		}
538		return false
539	}
540	
541	func newContainerUsageSamplesWithKey(metrics *metrics.ContainerMetricsSnapshot) []*model.ContainerUsageSampleWithKey {
542		var samples []*model.ContainerUsageSampleWithKey
543	
544		for metricName, resourceAmount := range metrics.Usage {
545			sample := &model.ContainerUsageSampleWithKey{
546				Container: metrics.ID,
547				ContainerUsageSample: model.ContainerUsageSample{
548					MeasureStart: metrics.SnapshotTime,
549					Resource:     metricName,
550					Usage:        resourceAmount,
551				},
552			}
553			samples = append(samples, sample)
554		}
555		return samples
556	}
