564	func (feeder *clusterStateFeeder) validateTargetRef(ctx context.Context, vpa *vpa_types.VerticalPodAutoscaler) (bool, condition) {
565		//
566		if vpa.Spec.TargetRef == nil {
567			return false, condition{}
568		}
569	
570		target := fmt.Sprintf("%s.%s/%s", vpa.Spec.TargetRef.APIVersion, vpa.Spec.TargetRef.Kind, vpa.Spec.TargetRef.Name)
571	
572		k := controllerfetcher.ControllerKeyWithAPIVersion{
573			ControllerKey: controllerfetcher.ControllerKey{
574				Namespace: vpa.Namespace,
575				Kind:      vpa.Spec.TargetRef.Kind,
576				Name:      vpa.Spec.TargetRef.Name,
577			},
578			ApiVersion: vpa.Spec.TargetRef.APIVersion,
579		}
580		top, err := feeder.controllerFetcher.FindTopMostWellKnownOrScalable(ctx, &k)
581		if err != nil {
582			return false, condition{conditionType: vpa_types.ConfigUnsupported, delete: false, message: fmt.Sprintf("Error checking if target %s is a topmost well-known or scalable controller: %s", target, err)}
583		}
584		if top == nil {
585			return false, condition{conditionType: vpa_types.ConfigUnsupported, delete: false, message: fmt.Sprintf("Unknown error during checking if target %s is a topmost well-known or scalable controller", target)}
586		}
587		if *top != k {
588			return false, condition{conditionType: vpa_types.ConfigUnsupported, delete: false, message: fmt.Sprintf("The target %s has a parent controller but it should point to a topmost well-known or scalable controller", target)}
589		}
590		return true, condition{}
591	}
592	
593	func (feeder *clusterStateFeeder) getSelector(ctx context.Context, vpa *vpa_types.VerticalPodAutoscaler) (labels.Selector, []condition) {
594		selector, fetchErr := feeder.selectorFetcher.Fetch(ctx, vpa)
595		if selector != nil {
596			validTargetRef, unsupportedCondition := feeder.validateTargetRef(ctx, vpa)
597			if !validTargetRef {
598				return labels.Nothing(), []condition{
599					unsupportedCondition,
600					{conditionType: vpa_types.ConfigDeprecated, delete: true},
601				}
602			}
603			return selector, []condition{
604				{conditionType: vpa_types.ConfigUnsupported, delete: true},
605				{conditionType: vpa_types.ConfigDeprecated, delete: true},
606			}
607		}
608		msg := "Cannot read targetRef"
609		if fetchErr != nil {
610			klog.ErrorS(fetchErr, "Cannot get target selector from VPA's targetRef")
611			msg = fmt.Sprintf("Cannot read targetRef. Reason: %s", fetchErr.Error())
612		}
613		return labels.Nothing(), []condition{
614			{conditionType: vpa_types.ConfigUnsupported, delete: false, message: msg},
615			{conditionType: vpa_types.ConfigDeprecated, delete: true},
616		}
617	}
