213		// Prometheus history provider flags
214		flag.StringVar(&config.PrometheusAddress, "prometheus-address", config.PrometheusAddress, `Where to reach for Prometheus metrics`)
215		flag.BoolVar(&config.PrometheusInsecure, "prometheus-insecure", config.PrometheusInsecure, `Skip TLS verification if HTTPS is used in the prometheus-address`)
216		flag.StringVar(&config.PrometheusJobName, "prometheus-cadvisor-job-name", config.PrometheusJobName, `Name of the Prometheus job which scrapes the cAdvisor metrics`)
217		flag.StringVar(&config.HistoryLength, "history-length", config.HistoryLength, `How much time back Prometheus has to be queried to get historical metrics`)
218		flag.StringVar(&config.HistoryResolution, "history-resolution", config.HistoryResolution, `Resolution at which Prometheus is queried for historical metrics`)
