266	// ValidateRecommenderConfig performs validation of the recommender flags
267	func ValidateRecommenderConfig(config *RecommenderConfig) {
268		common.ValidateCommonConfig(config.CommonFlags)
269	
270		if config.MinCheckpointsPerRun != 10 { // Default value is 10
271			klog.InfoS("DEPRECATION WARNING: The 'min-checkpoints' flag is deprecated and has no effect. It will be removed in a future release.")
272		}
273	
274		if config.PrometheusBearerToken != "" && config.PrometheusBearerTokenFile != "" && config.Username != "" {
275			klog.ErrorS(nil, "--bearer-token, --bearer-token-file and --username are mutually exclusive and can't be set together.")
276			klog.FlushAndExit(klog.ExitFlushTimeout, 1)
277		}
278	
279		if config.PrometheusBearerTokenFile != "" {
280			fileContent, err := os.ReadFile(config.PrometheusBearerTokenFile)
281			if err != nil {
282				klog.ErrorS(err, "Unable to read bearer token file", "filename", config.PrometheusBearerTokenFile)
283				klog.FlushAndExit(klog.ExitFlushTimeout, 1)
284			}
285			config.PrometheusBearerToken = strings.TrimSpace(string(fileContent))
286		}
287	}
