 46		// aggregateContainerStateGCInterval defines how often expired AggregateContainerStates are garbage collected.
 47		aggregateContainerStateGCInterval               = 1 * time.Hour
 48		scaleCacheEntryLifetime           time.Duration = time.Hour
 49		scaleCacheEntryFreshnessTime      time.Duration = 10 * time.Minute
 50		scaleCacheEntryJitterFactor       float64       = 1.
 51		scaleCacheLoopPeriod                            = 7 * time.Second
