 54	// RecommenderController wraps the Recommender with the full lifecycle
 55	// (informer setup, ticker loop, health checks) needed to run as a standalone controller.
 56	// It implements controllercontext.Controller.
 57	type RecommenderController struct {
 58		recommender Recommender
 59		healthCheck *metrics.HealthCheck
 60		config      *recommender_config.RecommenderConfig
 61	}
 62	
 63	// NewRecommenderController creates a RecommenderController
 64	func NewRecommenderController(
 65		ctx context.Context,
 66		kubeConfig *rest.Config,
 67		kubeClient kube_client.Interface,
 68		vpaClient *vpa_clientset.Clientset,
 69		factory informers.SharedInformerFactory,
 70		config *recommender_config.RecommenderConfig,
 71		healthCheck *metrics.HealthCheck,
 72		stopCh <-chan struct{},
 73	) (*RecommenderController, error) {
 74		commonFlags := config.CommonFlags
 75	
 76		clusterState := model.NewClusterState(aggregateContainerStateGCInterval)
 77		controllerFetcher := controllerfetcher.NewControllerFetcher(kubeConfig, kubeClient, factory, scaleCacheEntryFreshnessTime, scaleCacheEntryLifetime, scaleCacheEntryJitterFactor, stopCh)
 78		podLister, oomObserver := input.NewPodListerAndOOMObserver(ctx, kubeClient, commonFlags.VpaObjectNamespace, stopCh)
 79	
 80		model.InitializeAggregationsConfig(model.NewAggregationsConfig(
 81			config.MemoryAggregationInterval,
 82			config.MemoryAggregationIntervalCount,
 83			config.MemoryHistogramDecayHalfLife,
 84			config.CpuHistogramDecayHalfLife,
 85			config.OOMBumpUpRatio,
 86			config.OOMMinBumpUp,
 87		))
 88	
 89		useCheckpoints := config.Storage != "prometheus"
 90	
 91		var postProcessors []RecommendationPostProcessor
 92		if config.PostProcessorCPUasInteger {
 93			postProcessors = append(postProcessors, &IntegerCPUPostProcessor{})
 94		}
 95	
 96		globalMaxAllowed := initGlobalMaxAllowed(config)
 97		postProcessors = append(postProcessors, NewCappingRecommendationProcessor(globalMaxAllowed))
 98	
 99		var source input_metrics.PodMetricsLister
100		if config.UseExternalMetrics {
101			resourceMetrics := map[corev1.ResourceName]string{}
102			if config.ExternalCpuMetric != "" {
103				resourceMetrics[corev1.ResourceCPU] = config.ExternalCpuMetric
104			}
105			if config.ExternalMemoryMetric != "" {
106				resourceMetrics[corev1.ResourceMemory] = config.ExternalMemoryMetric
107			}
108			externalClientOptions := &input_metrics.ExternalClientOptions{
109				ResourceMetrics:    resourceMetrics,
110				ContainerNameLabel: config.CtrNameLabel,
111			}
112			klog.V(1).InfoS("Using External Metrics", "options", externalClientOptions)
113			source = input_metrics.NewExternalClient(kubeConfig, clusterState, *externalClientOptions)
114		} else {
115			klog.V(1).InfoS("Using Metrics Server")
116			source = input_metrics.NewPodMetricsesSource(resourceclient.NewForConfigOrDie(kubeConfig))
117		}
118	
119		ignoredNamespaces := strings.Split(commonFlags.IgnoredVpaObjectNamespaces, ",")
120	
121		clusterStateFeeder := input.ClusterStateFeederFactory{
122			PodLister:           podLister,
123			OOMObserver:         oomObserver,
124			MetricsClient:       input_metrics.NewMetricsClient(source, commonFlags.VpaObjectNamespace, "default-metrics-client"),
125			VpaCheckpointClient: vpaClient.AutoscalingV1(),
126			VpaLister:           vpa_api_util.NewVpasLister(vpaClient, stopCh, commonFlags.VpaObjectNamespace),
127			VpaCheckpointLister: vpa_api_util.NewVpaCheckpointLister(vpaClient, stopCh, commonFlags.VpaObjectNamespace),
128			ClusterState:        clusterState,
129			SelectorFetcher:     target.NewVpaTargetSelectorFetcher(kubeConfig, kubeClient, factory, stopCh),
130			MemorySaveMode:      config.MemorySaver,
131			ControllerFetcher:   controllerFetcher,
132			RecommenderName:     config.RecommenderName,
133			IgnoredNamespaces:   ignoredNamespaces,
134			VpaObjectNamespace:  commonFlags.VpaObjectNamespace,
135		}.Make()
136		controllerFetcher.Start(ctx, scaleCacheLoopPeriod)
137	
138		recommender := RecommenderFactory{
139			ClusterState:       clusterState,
140			ClusterStateFeeder: clusterStateFeeder,
141			ControllerFetcher:  controllerFetcher,
142			CheckpointWriter:   checkpoint.NewCheckpointWriter(clusterState, vpaClient.AutoscalingV1()),
143			VpaClient:          vpaClient.AutoscalingV1(),
144			PodResourceRecommender: logic.CreatePodResourceRecommender(logic.RecommendationConfig{
145				SafetyMarginFraction:       config.SafetyMarginFraction,
146				PodMinCPUMillicores:        config.PodMinCPUMillicores,
147				PodMinMemoryMb:             config.PodMinMemoryMb,
148				TargetCPUPercentile:        config.TargetCPUPercentile,
149				LowerBoundCPUPercentile:    config.LowerBoundCPUPercentile,
150				UpperBoundCPUPercentile:    config.UpperBoundCPUPercentile,
151				ConfidenceIntervalCPU:      config.ConfidenceIntervalCPU,
152				TargetMemoryPercentile:     config.TargetMemoryPercentile,
153				LowerBoundMemoryPercentile: config.LowerBoundMemoryPercentile,
154				UpperBoundMemoryPercentile: config.UpperBoundMemoryPercentile,
155				ConfidenceIntervalMemory:   config.ConfidenceIntervalMemory,
156			}),
157			RecommendationFormat: logic.RecommendationFormat{
158				HumanizeMemory:     config.HumanizeMemory,
159				RoundCPUMillicores: config.RoundCPUMillicores,
160				RoundMemoryBytes:   config.RoundMemoryBytes,
161			},
162			RecommendationPostProcessors: postProcessors,
163			CheckpointsGCInterval:        config.CheckpointsGCInterval,
164			CheckpointsWriteTimeout:      config.CheckpointsWriteTimeout,
165			UseCheckpoints:               useCheckpoints,
166			UpdateWorkerCount:            config.UpdateWorkerCount,
167		}.Make()
168	
169		return &RecommenderController{
170			recommender: recommender,
171			healthCheck: healthCheck,
172			config:      config,
173		}, nil
174	}
