199	func initGlobalMaxAllowed(config *recommender_config.RecommenderConfig) corev1.ResourceList {
200		result := make(corev1.ResourceList)
201		if !config.MaxAllowedCPU.IsZero() {
202			result[corev1.ResourceCPU] = config.MaxAllowedCPU.Quantity
203		}
204		if !config.MaxAllowedMemory.IsZero() {
205			result[corev1.ResourceMemory] = config.MaxAllowedMemory.Quantity
206		}
207		return result
208	}
