210	func initHistoryProvider(ctx context.Context, rec Recommender, config *recommender_config.RecommenderConfig) error {
211		useCheckpoints := config.Storage != "prometheus"
212		if useCheckpoints {
213			rec.GetClusterStateFeeder().InitFromCheckpoints(ctx)
214		} else {
215			histConfig, err := newPrometheusHistoryProviderConfig(config)
216			if err != nil {
217				return err
218			}
219			provider, err := history.NewPrometheusHistoryProvider(histConfig)
220			if err != nil {
221				return err
222			}
223			rec.GetClusterStateFeeder().InitFromHistoryProvider(provider)
224		}
225		return nil
226	}
227	
228	func newPrometheusHistoryProviderConfig(config *recommender_config.RecommenderConfig) (history.PrometheusHistoryProviderConfig, error) {
229		promQueryTimeout, err := time.ParseDuration(config.QueryTimeout)
230		if err != nil {
231			return history.PrometheusHistoryProviderConfig{}, err
232		}
233		return history.PrometheusHistoryProviderConfig{
234			Address:                config.PrometheusAddress,
235			Insecure:               config.PrometheusInsecure,
236			QueryTimeout:           promQueryTimeout,
237			HistoryLength:          config.HistoryLength,
238			HistoryResolution:      config.HistoryResolution,
239			PodLabelPrefix:         config.PodLabelPrefix,
240			PodLabelsMetricName:    config.PodLabelsMetricName,
241			PodNamespaceLabel:      config.PodNamespaceLabel,
242			PodNameLabel:           config.PodNameLabel,
243			CtrNamespaceLabel:      config.CtrNamespaceLabel,
244			CtrPodNameLabel:        config.CtrPodNameLabel,
245			CtrNameLabel:           config.CtrNameLabel,
246			CadvisorMetricsJobName: config.PrometheusJobName,
247			Namespace:              config.CommonFlags.VpaObjectNamespace,
248			CPUMetricName:          config.HistoryCPUMetric,
249			MemoryMetricName:       config.HistoryMemoryMetric,
250			Authentication: history.PrometheusCredentials{
251				BearerToken: config.PrometheusBearerToken,
252				Username:    config.Username,
253				Password:    config.Password,
254			},
255		}, nil
256	}

   270	
   271		vpas := feeder.clusterState.VPAs()
   272		for _, checkpoint := range checkpointList {
   273			vpaID := model.VpaID{Namespace: checkpoint.Namespace, VpaName: checkpoint.Spec.VPAObjectName}
   274			vpa, found := vpas[vpaID]
   275			if !found {
   276				klog.V(4).InfoS("Skipping loading checkpoint: VPA not tracked by this recommender", "checkpoint", klog.KObj(checkpoint), "vpa", klog.KRef(vpaID.Namespace, vpaID.VpaName), "recommenderName", feeder.recommenderName)
   277				continue
   278			}
   279			klog.V(3).InfoS("Loading checkpoint for VPA", "checkpoint", klog.KObj(checkpoint), "vpa", klog.KRef(vpaID.Namespace, vpaID.VpaName), "container", checkpoint.Spec.ContainerName)
   280			cs := model.NewAggregateContainerState()
   281			if err := cs.LoadFromCheckpoint(&checkpoint.Status); err != nil {
   282				klog.ErrorS(err, "Failed loading checkpoint", "checkpoint", klog.KObj(checkpoint), "vpa", klog.KRef(vpaID.Namespace, vpaID.VpaName))
   283				continue
   284			}
   285			vpa.ContainersInitialAggregateState[checkpoint.Spec.ContainerName] = cs
   286		}
   287	}
